  @override
  String get aboutPrivacyContent =>
      'يحترم Stroom خصوصية جميع مستخدمي الخدمة ويحميها.\n\n1. إذن الكاميرا: يُستخدم لالتقاط الصور فقط. لا يتم جمع بيانات الصور أو رفعها.\n\n2. إذن مكتبة الصور: يُستخدم لاختيار الصور وحفظها فقط. تُخزّن جميع الصور محليًا على جهازك.\n\n3. أمن البيانات: تُخزّن جميع الصور التي تلتقطها محليًا على جهازك. لا نصل إلى بياناتك ولا نرفعها.\n\n4. خدمات الجهات الخارجية: لا يتضمن هذا التطبيق أي خدمات تحليلات أو إعلانات تابعة لجهات خارجية.\n\nتواصل معنا إن كانت لديك أسئلة.';

