  @override
  String get batchDlgHelpBody =>
      '1. اختر إعدادًا مسبقًا أو فعّل القواعد، ثم انسخ القواعد وعدّل ترتيبها عند الحاجة.\n\n2. تعرض المعاينة الأسماء التي ستُستخدم. تؤثر عمليات البحث والتصفية على العرض فقط. يؤدي إلغاء تحديد عنصر إلى استبعاده وإعادة حساب الترقيم. عدّل الاسم منفردًا أو استعد نتيجة القاعدة.\n\n3. عالج جميع المشكلات قبل التشغيل. تعالج اللواحق التلقائية الأسماء المكررة من دون استبدال الملفات. أعد تسمية المجلدات التي ستتبادل الأسماء في دفعات منفصلة.\n\n4. يمكنك إيقاف العناصر اللاحقة أثناء التنفيذ؛ ويكتمل العنصر الحالي أولًا. تعرض صفحة النتائج التغييرات المكتملة وتتيح التراجع عنها. يُمنع التراجع إذا تغيرت القائمة منذ التنفيذ.\n\nيغيّر هذا الإجراء أسماء الملفات ومسارات المجلدات فقط؛ ولا يغيّر محتويات الملفات أو امتداداتها. لا يمنع تغيير اسم المجلد الأصلي إعادة تسمية عناصره الفرعية المحددة، كما يؤدي تغيير اسم المجلد الأصلي إلى نقل عناصره الفرعية معه.';

