  @override
  String fileManagerDeleteEmptyFolderWithSubfoldersConfirm(
    num count,
    Object name,
  ) {
    String _temp0 = intl.Intl.pluralLogic(
      count,
      locale: localeName,
      other: '$count مجلد فرعي.',
      many: '$count مجلدًا فرعيًا.',
      few: '$count مجلدات فرعية.',
      two: 'مجلدان فرعيان.',
      one: 'مجلد فرعي واحد.',
      zero: '0 مجلدات فرعية.',
    );
    return 'هل تريد حذف المجلد الفارغ «$name»؟ سيُحذف أيضًا $_temp0';
