  @override
  String get backgroundOptimizationWatchdogDetail =>
      'عند التفعيل، يتحقق Android من خدمة الخلفية كل 5 دقائق باستخدام تنبيه أصلي. إذا أوقف النظام العملية، يعيد التنبيه تشغيلها.\n\nيستمر التنبيه في وضع Doze ويُعاد جدولته بعد إعادة التشغيل.\n\nموصى به للمستخدمين الذين يعتمدون كثيرًا على مهام الخلفية.\nتأثير البطارية: منخفض جدًا؛ إذ يستيقظ الجهاز لفترة وجيزة عند كل تحقق.';

  @override
  String get backgroundOptimizationSaveWatchdogFailed =>
      'تعذّر حفظ إعداد المراقب؛ ولم يتغير.';

  @override
