  @override
  String get backgroundOptimizationColdStartTitle =>
      'استعادة الخدمة عند فتح التطبيق';

  @override
  String get backgroundOptimizationColdStartDetail =>
      'عند التفعيل، يتحقق التطبيق من وجود خدمة خلفية كانت تعمل سابقًا ويستعيدها في كل مرة يُفتح فيها.\n\nإذا أوقف النظام أو المستخدم عملية التطبيق، فستُعاد خدمة الخلفية عند فتح التطبيق في المرة التالية.\n\nموصى به لجميع المستخدمين.\nتأثير البطارية: لا شيء؛ إذ يتحقق التطبيق مرة واحدة عند التشغيل.';

  @override
  String get backgroundOptimizationSaveColdStartFailed =>
      'تعذّر حفظ إعداد الاستعادة عند التشغيل؛ ولم يتغير.';

  @override
  String get backgroundOptimizationBatteryReminderTitle =>
      'تذكير بتحسين البطارية';

  @override
  String get backgroundOptimizationBatteryReminderDetail =>
      'عند التفعيل، تعرض هذه الصفحة حالة تحسين البطارية. إذا لم يكن التطبيق ضمن قائمة الاستثناءات من قيود البطارية، فيمكنك فتح إعدادات النظام لإضافته إليها.\n\nيحد تحسين البطارية في Android (Doze) من عمل التطبيقات في الخلفية. تمنع إضافة هذا التطبيق إلى قائمة الاستثناءات النظام من إيقافه لتوفير الطاقة.\n\nلا يؤدي إيقاف هذا الخيار إلا إلى إخفاء بطاقة التذكير؛ ولا يغيّر استثناء التطبيق من تحسين البطارية.';

  @override
  String get backgroundOptimizationStrategyIntro =>
      'يمكن تفعيل هذه الاستراتيجيات بشكل مستقل. جميعها مفعّلة افتراضيًا لضمان موثوقية أعلى لنشاط الخلفية. يؤثر إيقاف أحدها في تلك الاستراتيجية فقط، ولا يؤثر في خدمة الخلفية نفسها.';

  @override
  String get backgroundOptimizationIosNoteTitle => 'مهام الخلفية في iOS';

  @override
  String get backgroundOptimizationIosSupported =>
      'يدعم هذا الإصدار من iOS (26 أو أحدث) مهام الخلفية المستمرة. تستمر المهام عادةً عند الانتقال إلى تطبيق آخر أو قفل الشاشة، لكن قد يوقفها النظام عند انخفاض الموارد. يمكنك عرض التقدم على شاشة القفل.';

  @override
  String get backgroundOptimizationIosUnsupported =>
      'لا يدعم هذا الإصدار من iOS (أقدم من 26) مهام الخلفية المستمرة. أثناء تشغيل مهمة، عُد إلى التطبيق كل بضع دقائق (نحو كل 5–10 دقائق؛ ويعتمد التوقيت على iOS) لتجديد وقت عمله في الخلفية ومنع تعليقه.';

  @override
  String get backgroundOptimizationIosWarning =>
      'في جميع إصدارات iOS، لا تُزِل Stroom بالسحب من مبدّل التطبيقات. يؤدي ذلك إلى إيقاف جميع المهام قيد التشغيل فورًا.';

  @override
  String get backgroundOptimizationDesktopIntro =>
