  @override
  String get backgroundOptimizationCloseMinimizeDetail =>
      'عند التفعيل، يؤدي النقر على زر إغلاق النافذة إلى إخفاء التطبيق في علبة النظام بدلًا من إنهائه. وتستمر مهام الخلفية في العمل.\n\nاستعد النافذة من أيقونة علبة النظام أو عنصر القائمة «إظهار النافذة الرئيسية». للخروج، استخدم زر «إنهاء التطبيق» أدناه.\n\nموصى به لجميع مستخدمي سطح المكتب.';

