  @override
  String get platformTutorialAndroidStep1Description =>
      'افتح الإعدادات ← التطبيقات ← Stroom ← البطارية، ثم اختر «بلا قيود» أو «عدم التحسين». يمكنك أيضًا الضغط على «تجاهل تحسين البطارية» في صفحة «تحسين العمل في الخلفية» للتطبيق لإضافة Stroom إلى قائمة السماح بتوفير الطاقة في النظام. تختلف المسارات حسب الشركة المصنّعة للجهاز.';

  @override
  String get platformTutorialAndroidStep2Title => 'السماح بنشاط الخلفية';

  @override
  String get platformTutorialAndroidStep2Description =>
      'افتح الإعدادات ← التطبيقات ← Stroom وفعّل «السماح بنشاط الخلفية» و«السماح بالتشغيل التلقائي». تتطلب بعض الهواتف أيضًا السماح بالتشغيل التلقائي من مركز الأمان أو مدير الهاتف.';

  @override
  String get platformTutorialAndroidStep3Title => 'قفل العملية في الخلفية';

  @override
  String get platformTutorialAndroidStep3Description =>
      'في عرض التطبيقات الحديثة، اسحب بطاقة Stroom إلى الأسفل أو اضغط أيقونة القفل لمنع النظام من إغلاق التطبيق.';

  @override
  String get platformTutorialAndroidStep4Title =>
      'السماح بالإشعارات (Android 13 فأحدث)';

  @override
  String get platformTutorialAndroidStep4Description =>
      'يتطلب Android 13 والإصدارات الأحدث إذن الإشعارات. من دونه، يُخفى إشعار الخدمة الأمامية مع استمرار عمل الخدمة. يطلب التطبيق الإذن عند الضغط على «بدء الخدمة» لأول مرة، أو يمكنك تفعيله من الإعدادات ← التطبيقات ← Stroom ← الإشعارات.';

  @override
  String get platformTutorialAndroidStep5Title => 'تجاهل تحسين البطارية';

  @override
  String get platformTutorialAndroidStep5Description =>
      'عند تفعيل «إشعارات اكتمال المهمة» في Stroom، يطلب التطبيق الإذن المرتبط بها. يمكنك أيضًا التأكد من ضبط Stroom على «عدم التحسين» من الإعدادات ← التطبيقات ← وصول خاص للتطبيقات ← تحسين البطارية.';

  @override
  String get platformTutorialAndroidStep6Title =>
      'التشغيل التلقائي وإدارة الخلفية على أجهزة Android';

  @override
  String get platformTutorialAndroidStep6Description =>
      'تضيف الشركات المصنّعة للأجهزة عادةً عناصر تحكم خاصة بها في الخلفية:\n• Xiaomi/Redmi (MIUI/HyperOS): الإعدادات ← التطبيقات ← الأذونات ← التشغيل التلقائي؛ اسمح لـ Stroom. ثم افتح البطارية ← موفّر بطارية التطبيقات ← Stroom ← بلا قيود.\n• Huawei/Honor (EMUI/HarmonyOS): الإعدادات ← التطبيقات ← تشغيل التطبيق ← Stroom ← إدارة يدويًا؛ اسمح بالتشغيل التلقائي والتشغيل الثانوي ونشاط الخلفية.\n• OPPO/OnePlus/realme (ColorOS): الإعدادات ← البطارية ← إدارة بطارية التطبيقات ← Stroom؛ اسمح بنشاط الخلفية الكامل.\n• vivo/iQOO (OriginOS): iManager ← إدارة التطبيقات ← التشغيل التلقائي؛ اسمح لـ Stroom.';

  @override
  String get platformTutorialAndroidStep7Title =>
      'إيقاف تنظيف شاشة القفل وأنماط توفير الطاقة';

  @override
  String get platformTutorialAndroidStep7Description =>
      'افتح الإعدادات ← البطارية وأوقف «توفير الطاقة» أو «توفير الطاقة الفائق». واضبط «مسح الذاكرة بعد القفل» على «عدم المسح». تقيّد أنماط توفير الطاقة نشاط الخلفية وقد تؤثر في اكتمال المهام.';

  @override
  String get platformTutorialIosStep1Title =>
      'تفعيل تحديث التطبيقات في الخلفية';

  @override
  String get platformTutorialIosStep1Description =>
      'افتح الإعدادات ← عام ← تحديث التطبيقات في الخلفية، وابحث عن Stroom وفعّله. اختر «Wi-Fi والبيانات الخلوية» للحصول على أفضل تجربة.';

  @override
  String get platformTutorialIosStep2Title => 'السماح بالإشعارات';

  @override
  String get platformTutorialIosStep2Description =>
      'افتح الإعدادات ← الإشعارات ← Stroom وفعّل «السماح بالإشعارات». فعّل اللافتات ومركز الإشعارات لتلقي تحديثات المهام فورًا.';

  @override
  String get platformTutorialIosStep3Title => 'إيقاف نمط الطاقة المنخفضة';

  @override
  String get platformTutorialIosStep3Description =>
      'افتح الإعدادات ← البطارية وأوقف «نمط الطاقة المنخفضة». يقيّد النظام نشاط الخلفية عند تشغيل هذا النمط.';

  @override
  String get platformTutorialIosStep4Title => 'فهم قيود الخلفية في iOS';

  @override
  String get platformTutorialIosStep4Description =>
      'لا تسمح الإصدارات السابقة لـ iOS 26 ببقاء التطبيقات في الخلفية كما في Android. يمنح النظام التطبيقات وقت تنفيذ وجيزًا في أوقات محددة فقط، مثل تحديث التطبيقات في الخلفية أو تحديثات الموقع أو تشغيل الصوت، وقد يعلّق المهام طويلة الأمد. نوصي بما يلي:\n• أبقِ Stroom في الواجهة أثناء المهام طويلة الأمد.\n• عُد إلى التطبيق دوريًا لتجديد وقت عمله في الخلفية.\n• فعّل «إشعارات اكتمال المهمة» للمهام المهمة.';

  @override
  String get platformTutorialIosStep5Title =>
      'نصائح الخلفية أثناء تشغيل المهام';

  @override
  String get platformTutorialIosStep5Description =>
      'يدعم iOS 26 والإصدارات الأحدث مهام الخلفية المستمرة. تستمر المهام عادةً عند الانتقال إلى تطبيق آخر أو قفل الشاشة، لكن قد يوقفها النظام عند ندرة الموارد؛ ويظهر التقدم على شاشة القفل.\n\nلا تدعم إصدارات iOS الأقدم مهام الخلفية المستمرة. عُد إلى التطبيق كل بضع دقائق (من 5 إلى 10 دقائق دليل تقريبي؛ والنظام هو من يقرر) لتجديد وقت الخلفية ومنع التعليق.\n\nفي جميع الإصدارات، لا تُزِل Stroom بالسحب من مبدّل التطبيقات؛ إذ يؤدي ذلك إلى إيقاف جميع المهام فورًا.';

  @override
  String get platformTutorialIosStep6Title => 'إبقاء التطبيق في الواجهة';

  @override
  String get platformTutorialIosStep6Description =>
      'في الإصدارات السابقة لـ iOS 26، يكون وقت عمل التطبيقات في الخلفية محدودًا. للمهام طويلة الأمد، أبقِ Stroom في الواجهة أو عُد إليه دوريًا لتمديد ذلك الوقت.';

  @override
  String get platformTutorialWindowsStep1Title => 'التصغير عند إغلاق النافذة';

  @override
  String get platformTutorialWindowsStep1Description =>
      'افتراضيًا، يؤدي النقر على زر إغلاق النافذة إلى تصغير Stroom إلى علبة النظام (بالقرب من الساعة) ليستمر تشغيله. استعده من أيقونة العلبة أو قائمة «إظهار النافذة الرئيسية». لا تنه التطبيق أثناء تشغيل المهام. للخروج، استخدم «إنهاء التطبيق بالكامل» في صفحة «تحسين العمل في الخلفية» أو اختر «إنهاء Stroom» من قائمة العلبة.';

  @override
  String get platformTutorialWindowsStep2Title => 'إيقاف موفّر البطارية';

  @override
  String get platformTutorialWindowsStep2Description =>
      'افتح الإعدادات ← النظام ← الطاقة والسكون وأوقف موفّر البطارية. ويمكنك بدلًا من ذلك ضبطه للعمل فقط عندما تنخفض البطارية إلى مستوى تختاره.';

  @override
  String get platformTutorialWindowsStep3Title => 'السماح بتطبيقات الخلفية';

  @override
  String get platformTutorialWindowsStep3Description =>
      'افتح الإعدادات ← الخصوصية والأمان ← تطبيقات الخلفية، وابحث عن Stroom وتأكد من تفعيله. في Windows 11، انتقل إلى الإعدادات ← التطبيقات ← التطبيقات المثبتة ← Stroom ← خيارات متقدمة ← أذونات تطبيقات الخلفية واختر «دائمًا».';

  @override
  String get platformTutorialWindowsStep4Title => 'إيقاف نمط السكون (اختياري)';

  @override
  String get platformTutorialWindowsStep4Description =>
      'لإبقاء Stroom قيد التشغيل فترات طويلة، افتح الإعدادات ← النظام ← الطاقة واضبط «السكون» على «أبدًا» (عند توصيل الجهاز بالطاقة فقط).';

  @override
  String get platformTutorialWindowsStep5Title =>
      'إضافة Stroom إلى بدء التشغيل';

  @override
  String get platformTutorialWindowsStep5Description =>
      'افتح مدير المهام (Ctrl+Shift+Esc) ← بدء التشغيل، وابحث عن Stroom وانقر بزر الفأرة الأيمن على «تمكين». أو افتح الإعدادات ← التطبيقات ← بدء التشغيل وفعّل Stroom.';

  @override
  String get platformTutorialMacosStep1Title => 'التصغير عند إغلاق النافذة';

  @override
  String get platformTutorialMacosStep1Description =>
      'افتراضيًا، يؤدي إغلاق النافذة إلى استمرار تشغيل Stroom في شريط القوائم (أعلى يسار الشاشة). انقر أيقونة شريط القوائم أو اختر «إظهار النافذة الرئيسية» لاستعادتها. لا تنه التطبيق أثناء تشغيل المهام. للخروج، استخدم «إنهاء التطبيق بالكامل» في صفحة «تحسين العمل في الخلفية» أو اختر «إنهاء Stroom» من قائمة شريط القوائم.';

  @override
  String get platformTutorialMacosStep2Title => 'السماح بالإشعارات';

  @override
  String get platformTutorialMacosStep2Description =>
      'افتح إعدادات النظام ← الإشعارات ← Stroom وفعّل «السماح بالإشعارات». نوصي بتفعيل اللافتات ومركز الإشعارات.';

  @override
  String get platformTutorialMacosStep3Title =>
      'إيقاف نمط الطاقة المنخفضة (MacBook)';

  @override
  String get platformTutorialMacosStep3Description =>
      'افتح إعدادات النظام ← البطارية ← محول الطاقة وأوقف «نمط الطاقة المنخفضة». يقيّد هذا النمط نشاط الخلفية.';

  @override
  String get platformTutorialMacosStep4Title => 'إبقاء التطبيق نشطًا';

  @override
  String get platformTutorialMacosStep4Description =>
      'تفرض macOS قيودًا قليلة على تطبيقات الخلفية. للمهام طويلة الأمد، اترك نافذة Stroom مفتوحة. تجنب فرض إنهاء التطبيق؛ يكفي إغلاق النافذة.';

  @override
  String get platformTutorialMacosStep5Title =>
      'التشغيل عند تسجيل الدخول (اختياري)';

  @override
  String get platformTutorialMacosStep5Description =>
      'افتح إعدادات النظام ← عام ← عناصر تسجيل الدخول وأضف Stroom ليبدأ تلقائيًا عند تشغيل الكمبيوتر.';

  @override
  String get platformTutorialLinuxStep1Title => 'التصغير عند إغلاق النافذة';

  @override
  String get platformTutorialLinuxStep1Description =>
      'افتراضيًا، يؤدي إغلاق النافذة إلى إخفاء Stroom في علبة النظام (يتطلب ذلك بيئة سطح مكتب تدعم StatusNotifierItem وحزمة libayatana-appindicator3-dev وقت البناء). استعده من قائمة العلبة باختيار «إظهار النافذة الرئيسية». لا تنه التطبيق أثناء تشغيل المهام. للخروج، استخدم «إنهاء التطبيق بالكامل» في صفحة «تحسين العمل في الخلفية» أو اختر «إنهاء Stroom» من قائمة العلبة.';

  @override
  String get platformTutorialLinuxStep2Title => 'إعدادات بيئة سطح المكتب';

  @override
  String get platformTutorialLinuxStep2Description =>
      'وفقًا لبيئة سطح المكتب (GNOME أو KDE أو XFCE وغيرها)، افتح إعدادات النظام ← التطبيقات، وابحث عن Stroom وتأكد من عدم تقييد نشاط الخلفية.';

  @override
  String get platformTutorialLinuxStep3Title =>
      'استخدام خدمة systemd (اختياري)';

  @override
  String get platformTutorialLinuxStep3Description =>
      'للعمل طويل الأمد في الخلفية، أنشئ خدمة مستخدم systemd. أنشئ ملف stroom.service داخل ~/.config/systemd/user/ واضبط ExecStart على الملف التنفيذي لـ Stroom.';

  @override
  String get platformTutorialLinuxStep4Title => 'تعطيل السكون';

  @override
  String get platformTutorialLinuxStep4Description =>
      'لخادم أو جهاز سطح مكتب يحتاج إلى العمل مدة طويلة، اضبط HandleLidSwitch=ignore في /etc/systemd/logind.conf لمنع السكون عند إغلاق الغطاء.';

  @override
  String get platformTutorialLinuxStep5Title => 'تفعيل التشغيل التلقائي';

  @override
  String get platformTutorialLinuxStep5Description =>
      'في GNOME، استخدم Tweaks ← تطبيقات بدء التشغيل ← إضافة Stroom. أو أنشئ ملف stroom.desktop داخل ~/.config/autostart/.';

  @override
  String get platformTutorialWebStep1Title => 'إبقاء علامة التبويب مفتوحة';

  @override
  String get platformTutorialWebStep1Description =>
      'لا تدعم متصفحات الويب خدمات الخلفية. أبقِ علامة تبويب Stroom مفتوحة أثناء تشغيل المهام؛ إذ يؤدي إغلاقها أو تحديث الصفحة إلى مقاطعة المهام فورًا.';

  @override
  String get platformTutorialWebStep2Title =>
      'منع المتصفح من تعليق علامة التبويب';

  @override
  String get platformTutorialWebStep2Description =>
      'قد يجمّد المتصفح علامات التبويب الخلفية غير النشطة لتوفير الموارد. أبقِ علامة تبويب Stroom في الواجهة أثناء تشغيل المهام أو تفاعل مع الصفحة دوريًا لإبقائها نشطة.';

